# Author-side clarification before first independent science-first freeze; old drafts retained.
from pathlib import Path
import json,copy,hashlib
ROOT=Path.cwd();D=Path(__file__).resolve().parent;A=D.parent
def write(name,v):
 with (D/name).open('x') as f:f.write(json.dumps(v,ensure_ascii=False,indent=2)+'\n' if not isinstance(v,str) else v)
old=json.loads((A/'materials/twenty-whole-goals-forty-complete-DEEN-cases.author.json').read_text());m=copy.deepcopy(old)
c=m['goals'][0]['cases'][1];c['material']['de']=c['material']['de'].replace('sechs Wasserfrösche,','sechs Wasserfrösche derselben vorgegebenen Art,');c['material']['en']=c['material']['en'].replace('six water frogs,','six water frogs of one specified species,')
conditional=[]
for n in [10,11]:
 c=copy.deepcopy(m['goals'][n-1]['cases'][1]);c['originalCaseId']=c['id'];c['id']=f'flora-fauna20-{n:02d}-conditional-fish-case-1';conditional.append({'goalId':m['goals'][n-1]['goalId'],'sourceSelection':'HE6.2 fish as chosen depth instead of bird; no universal dual-depth demand','commonRequiredExpectation':False,'wholeOriginalFishChoiceCase':c})
g=m['goals'][9];c=g['cases'][1]
c['material']={'de':'Zweiter vorgegebener Vogelfall: Eine Ente besitzt Federflächen an den Flügeln, dichtes Gefieder und Schwimmhäute an den Füßen; ein Laufvogel hat kräftige lange Laufgliedmaßen und fliegt im gegebenen Beispiel nicht. Wasser, Luft und Land stellen unterschiedliche Bedingungen an Fortbewegung und Wärmehaushalt. Beide sind schematische Modelle, keine Messreihe.','en':'Second supplied bird case: a duck has feathered wings, dense plumage and webbed feet; a running bird has strong long legs and does not fly in this example. Water, air and land impose differing movement and thermal conditions. Both are schematic models rather than a measurement series.'}
c['task']={'de':'Deute die Vogelmerkmale mit ihren Funktionen als Angepasstheit an Lebensräume und begrenze Verallgemeinerungen über alle Vögel. Der gewählte Vertiefungsschwerpunkt bleibt Vogel.','en':'Interpret bird traits and their functions as habitat adaptations and bound generalizations about all birds. Bird remains the selected in-depth topic.'}
c['modelAnswer']={'de':'Federflächen und geeignete Flügelbewegung können Luftkräfte für Flug erzeugen; Schwimmhäute vergrößern die antreibende Fußfläche im Wasser. Dichtes Gefieder kann isolierende Luft einschließen und Wärmeverlust mindern. Kräftige Laufgliedmaßen übertragen Muskelkraft bei Bodenbewegung; ihr Bau passt zu einer anderen Bewegungsweise. Verschiedene Funktionen sind an die Bedingungen der jeweiligen Lebensräume gebunden, nicht an eine allgemeine Rangfolge. Nicht jeder Vogel fliegt, besitzt Schwimmhäute oder hat denselben Körperbau, und individuelle Absicht erzeugt keine neuen Anpassungsmerkmale. Beide gemeinsamen Fälle vertiefen Vögel; Fisch ist nur eine zulässige andere Quellenwahl.','en':'Feather surfaces and suitable wing motion can generate aerial forces for flight; webbing enlarges the propulsive foot area in water. Dense plumage can trap insulating air and reduce heat loss. Strong running legs transmit muscular force during ground movement and suit a different locomotion mode. Functions relate to habitat conditions rather than a ranking of superior birds. Not every bird flies, has webbing or shares one body form, and individual intention creates no new adaptations. Both common cases deepen birds; fish is a permissible alternative source choice.'}
g=m['goals'][10];c=g['cases'][1]
c['material']={'de':'Zweite synthetische Vogelstrategien: C verteidigt zur Brutzeit ein Revier, zeigt dort Balz und versorgt mit seinem Partner wenige Junge im Nest. D balzt und paart sich in einer Kolonie; um das eigene Nest wird nur ein kleiner Bereich verteidigt und beide Partner betreuen ebenfalls Junge. Zahl und Pflegeaufwand unterscheiden sich im Modell, tatsächliche Überlebensdaten fehlen.','en':'Second synthetic bird strategies: C defends a breeding territory, courts there and provides with its partner for few young in a nest. D courts and mates in a colony, defends only a small area around its own nest and both partners also care for young. Numbers and effort differ in the model; actual survival data are absent.'}
c['task']={'de':'Vergleiche Revierbildung, Balz/Paarung und Brutpflege einschließlich der Bedeutung von Nachkommenzahl; korrigiere die Aussage, Koloniebrut bedeute fehlende Nestpflege oder überhaupt keinen verteidigten Bereich.','en':'Compare territories, courtship/mating and brood care including offspring numbers; correct the claim that colonial breeding means no nest care or defended area at all.'}
c['modelAnswer']={'de':'C verbindet ein größeres Brutrevier mit Partnerwerbung und Zugang zu Ressourcen; D konzentriert räumliche Verteidigung auf den kleinen Nestbereich trotz gemeinschaftlicher Kolonie. In beiden Fällen stehen Balz/Partnerwahl und Paarung im Fortpflanzungszusammenhang, während Versorgung und Schutz der Jungen Pflegeinvestition darstellen. Nachkommenzahl und Aufwand je Jungtier sind gemeinsam zu betrachten; mehr oder weniger Nachkommen beweist ohne Umwelt-/Erfolgsdaten keine bessere Strategie. Koloniebrut beseitigt weder automatisch jede räumliche Verteidigung noch Brutpflege. Die Beispiele betreffen die gewählte Vogelvertiefung und begründen keine universelle Paarungs- oder Pflegeform.','en':'C links a larger breeding territory to mate attraction and resource access; D concentrates defence on a small nest area despite communal colony living. Both connect courtship/mate choice and mating to reproduction, while feeding and protecting young are care investments. Offspring number and per-young effort must be considered together; more or fewer offspring establishes no better strategy without environmental/success data. Colonial breeding removes neither all spatial defence nor brood care. These examples address selected bird depth rather than a universal mating or care form.'}
c=m['goals'][12]['cases'][1];c['material']['de']=c['material']['de'].replace('muss bei gleicher Bewegung mehr Wasser verdrängen','stört bei vergleichbarer Bewegung die Umströmung stärker und besitzt im Modell höheren Strömungswiderstand');c['material']['en']=c['material']['en'].replace('must move more water at matching motion','disturbs surrounding flow more and has higher model drag during comparable motion')
for o,n in zip(old['goals'],m['goals']):assert o['wholeGoal']==n['wholeGoal']
write('twenty-whole-goals-forty-common-DEEN-cases.author-v2.json',m)
write('two-explicit-conditional-fish-choice-alternatives.author-v2.json',{'role':'complete optional/source-choice alternatives, not serialized as common mandatory P expectations','cases':conditional,'humanApproval':False,'activeWrites':0})
md=['# Flora/Fauna20: vierzig ganze gemeinsame Fälle DE/EN','', 'Autoren-v2 vor unabhängiger Prüfung. HE6.2 gemeinsamer Vertiefungsschwerpunkt Vogel; vollständige Fischwahlfälle gesondert und bedingt. Keine reale Lernendenleistung.', '']
for g in m['goals']:
 md+=['## '+g['wholeGoal']['title'],'',g['wholeGoal']['description'],'',g['wholeGoal']['descriptionEn'],'']
 for c in g['cases']:
  md+=['### '+c['id'],'','**Material DE:** '+c['material']['de'],'','**Task DE:** '+c['task']['de'],'','**Model answer DE:** '+c['modelAnswer']['de'],'','**Material EN:** '+c['material']['en'],'','**Task EN:** '+c['task']['en'],'','**Model answer EN:** '+c['modelAnswer']['en'],'']
write('twenty-whole-goals-forty-common-DEEN-cases.author-v2.md','\n'.join(md)+'\n')
write('author-pre-first-seal-scope-science-precision.receipt.json',{'role':'author clarification before first independent freeze','originalUnmodifiedDraft':str((A/'materials/twenty-whole-goals-forty-complete-DEEN-cases.author.json').relative_to(ROOT)),'originalDraftSha256':hashlib.sha256((A/'materials/twenty-whole-goals-forty-complete-DEEN-cases.author.json').read_bytes()).hexdigest(),'changes':[{'ordinal':1,'case':2,'actualReason':'Water frogs are not one universal species; own fixture now explicitly states same specified species to support three-species count'},{'ordinal':10,'case':2,'actualReason':'HE6.2 bird OR fish depth; two common bird-depth cases and separate complete conditional fish choice, no universal dual-depth demand'},{'ordinal':11,'case':2,'actualReason':'Same source choice: common fresh bird reproductive-strategy case, old whole fish case preserved explicitly conditional'},{'ordinal':13,'case':2,'actualReason':'Blunt form increases disturbance/drag; greater total displaced volume is not the correct explanation of streamlining at matching form volume'}],'unchangedGoalBodies':20,'commonWholeCases':40,'conditionalWholeFishAlternatives':2,'independentApproval':False,'humanApproval':False,'activeWrites':0})
print(json.dumps({'commonWholeCases':40,'conditionalFishAlternatives':2,'unchangedGoalBodies':20,'authorOnly':True,'activeWrites':0}))
